// Code node "Format message" — Mode: Run Once for All Items
const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

return $input.all().map(({ json: j }) => {
  const snippet = j.text.length > 300 ? j.text.slice(0, 300) + '…' : j.text;

  const message = [
    `🆕 <b>${esc(j.title)}</b>`,
    `📂 ${esc(j.category)}`,
    `🔑 ${esc(j.matched_keywords.join(', '))}`,
    '',
    esc(snippet),
    '',
    `🔗 <a href="${esc(j.link)}">Відкрити на Djinni</a>`,
  ].join('\n');

  return { json: { ...j, message } };
});

// Code node "Keyword filter" — Mode: Run Once for All Items
// ===== НАЛАШТУВАННЯ (міняй тут) =====

// true  — пропускає ВСІ вакансії (для тестів)
// false — робочий режим
const TEST_MODE = false;

// Інструменти: шукаємо в назві І в описі
const TOOLS = ['n8n', 'make.com', 'zapier', 'integromat', 'pipedream'];

// Слова, які шукаємо ТІЛЬКИ в назві вакансії
const TITLE_WORDS = [
  'automation', 'автоматиз',
  'ai agent', 'ai-agent', 'ai агент', 'ai-агент',
  'chatbot', 'чат-бот', 'чатбот',
];

// Категорії, які відкидаємо завжди
const EXCLUDE_CATEGORIES = ['QA', 'QA Automation', 'Quality Assurance', 'QA Hardware / Embedded'];

// Рівні/ролі в назві, які не підходять
const EXCLUDE_TITLE = /\b(senior|sr|lead|head|architect|principal|director|cto|ceo)\b/i;
const EXCLUDE_QA_TITLE = /\bqa\b|test automation|automation test|тестувальник/i;

// ===== ЛОГІКА =====
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const title = (j.title || '').toLowerCase();
  const text = (j.text || '').toLowerCase();
  const category = j.category || '';

  if (TEST_MODE) {
    results.push({ json: { ...j, matched_keywords: ['TEST'] } });
    continue;
  }

  // 1. Відкидаємо явно непотрібне
  if (EXCLUDE_CATEGORIES.includes(category)) continue;
  if (EXCLUDE_TITLE.test(j.title || '') || EXCLUDE_QA_TITLE.test(j.title || '')) continue;

  // 2. Шукаємо збіги
  const matched = [
    ...TOOLS.filter(k => title.includes(k) || text.includes(k)),
    ...TITLE_WORDS.filter(k => title.includes(k)),
  ];

  if (matched.length === 0) continue;

  results.push({
    json: { ...j, matched_keywords: matched },
  });
}

return results;

// Code node — Mode: Run Once for All Items
const MAX_LEN = 6000; // максимальна довжина опису

// Прибирає HTML-теги і декодує сутності (&nbsp;, &amp; ...)
function htmlToText(html) {
  return String(html || '')
    .replace(/<\s*br\s*\/?>/gi, '\n')                 // <br> → новий рядок
    .replace(/<\/(p|li|ul|ol|h[1-6]|div)>/gi, '\n')   // кінець абзацу/пункту → новий рядок
    .replace(/<li[^>]*>/gi, '• ')                     // пункти списку → "• "
    .replace(/<[^>]+>/g, '')                          // решта тегів геть
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&amp;/g, '&')                           // &amp; останнім, щоб не декодувати двічі
    .replace(/[ \t]+/g, ' ')                          // зайві пробіли
    .replace(/\n\s*\n+/g, '\n')                       // зайві порожні рядки
    .trim();
}

const results = [];

for (const item of $input.all()) {
  const j = item.json;

  // 1. job_id з посилання: /jobs/853038-c-integration-engineer/ → 853038
  const link = j.link || j.guid || '';
  const idMatch = link.match(/\/jobs\/(\d+)/);
  if (!idMatch) continue; // без ID не зможемо відсікати дублі — пропускаємо

  // 2. Текст без HTML: чистимо самі (краще зберігає списки),
  //    а якщо HTML немає — беремо готовий contentSnippet
  const html = j.content || j.description || '';
  let text = html ? htmlToText(html) : String(j.contentSnippet || '').trim();

  // 3. Обрізаємо задовгий опис
  const truncated = text.length > MAX_LEN;
  if (truncated) text = text.slice(0, MAX_LEN) + '…';

  // Категорія: у фіді буває пустий <category/>, тому фільтруємо
  const categories = (Array.isArray(j.categories) ? j.categories : [j.categories])
    .map(c => (typeof c === 'string' ? c : c?._ ?? '').trim())
    .filter(Boolean);

  results.push({
    json: {
      job_id: Number(idMatch[1]),
      title: (j.title || '').trim(),
      link,
      category: categories[0] || '',
      published_at: j.isoDate || (j.pubDate ? new Date(j.pubDate).toISOString() : null),
      text,
      text_truncated: truncated,
    },
  });
}

return results;
